// Verus program to construct a Cartesian mesh grid from two non-empty Vec<f32>
verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>)
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // The two returned matrices each have y.len() rows
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| result.0.len() == y.len(),
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| result.1.len() == y.len(),
        // Each row in each matrix has x.len() columns
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| forall(|i: usize| i < y.len() ==> result.0[i].len() == x.len()),
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| forall(|i: usize| i < y.len() ==> result.1[i].len() == x.len()),
        // The (i,j)-entry of the first matrix is x[j]
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| forall(|i: usize, j: usize| i < y.len() && j < x.len() 
            ==> result.0[i][j] == x[j]),
        // The (i,j)-entry of the second matrix is y[i]
        |result: &(Vec<Vec<f32>>, Vec<Vec<f32>>)| forall(|i: usize, j: usize| i < y.len() && j < x.len() 
            ==> result.1[i][j] == y[i]),
{
    let n = x.len();
    let m = y.len();
    let mut X: Vec<Vec<f32>> = Vec::new();
    let mut Y: Vec<Vec<f32>> = Vec::new();
    let mut i: usize = 0;
    // Build each row of the meshgrid
    while i < m {
        invariant i <= m;
        invariant X.len() == i;
        invariant Y.len() == i;
        // All previously constructed rows satisfy the specification
        invariant forall(|k: usize|
            k < i ==>
                X[k].len() == n
                && forall(|j: usize| j < n ==> X[k][j] == x[j])
        );
        invariant forall(|k: usize|
            k < i ==>
                Y[k].len() == n
                && forall(|j: usize| j < n ==> Y[k][j] == y[k])
        );
        decreases m - i;

        // Construct row of X by copying all elements of x
        let mut row_x: Vec<f32> = Vec::new();
        let mut j: usize = 0;
        while j < n {
            invariant j <= n;
            invariant row_x.len() == j;
            invariant forall(|l: usize| l < j ==> row_x[l] == x[l]);
            decreases n - j;
            row_x.push(x[j]);
            j += 1;
        }

        // Construct row of Y by repeating y[i]
        let mut row_y: Vec<f32> = Vec::new();
        let mut j2: usize = 0;
        while j2 < n {
            invariant j2 <= n;
            invariant row_y.len() == j2;
            invariant forall(|l: usize| l < j2 ==> row_y[l] == y[i]);
            decreases n - j2;
            row_y.push(y[i]);
            j2 += 1;
        }

        X.push(row_x);
        Y.push(row_y);
        i += 1;
    }

    (X, Y)
}

} // end verus!